/* PixelForge · Secuencia de hielo extraída de la referencia suministrada.
   6 poses originales, orden de lectura 3×2. Mismo tamaño por celda.
   Paleta compartida de 192 colores. RLE codifica un índice por píxel; 0=transparente.
   Nota: estas seis poses son claves; no se han inventado intermedios. */
function createIceSequenceScene(){
 const width=256,height=208,fps=6,frames=6;
 const palette=[null,"#FAFEFE","#F3FEFD","#F0FFFD","#EFFBF9","#EBFEFD","#EAFDF7","#EAFAF8","#E5FDFA","#E5FBF8","#E4FBF4","#E4F9F5","#DDFCF9","#DFF8F4","#EBF5F4","#E3F5F3","#E0F5F3","#DBF5F6","#DDF4ED","#E3EFEE","#DAEFED","#DCE6E5","#CDFDFD","#B9FDFC","#CEF2F4","#B9F3F5","#A5FCFA","#97FCF8","#9DF2F5","#CFE3E5","#CDD9D8","#AEDEEB","#C4D0D0","#BEC6C6","#AAC6D3","#87FBF7","#87F1F3","#73FAF6","#72F1EF","#7BE2ED","#79C9E9","#61EDF0","#4DEBEA","#59CBE4","#41C8E3","#ACB8B9","#A4ACAC","#8CAECA","#979E9F","#849AAE","#899290","#6EB5F6","#6AB5DB","#6BA7E6","#689CF2","#6691ED","#6794C2","#7C8495","#7D8387","#7D8483","#767B82","#7A7F7B","#767B7A","#74777A","#6384E0","#6580A0","#6A7C85","#6C7881","#6A767D","#4DB6DF","#4DACDA","#4DA4D8","#35B0DD","#35A4D7","#4F96E8","#4E96C7","#3C97CD","#2A96D2","#5288E3","#4789E3","#4B7EE1","#4D86C4","#5084A6","#4C79B0","#3C84E0","#3B7AE0","#3A7FB1","#2681DF","#2780AB","#5F6F9A","#66707F","#6A7078","#4572C2","#4669BC","#4A6F97","#496691","#717270","#687170","#6B6A6B","#636C6C","#636567","#59686A","#495EA0","#4D5D78","#5E606A","#4B5B6B","#5E6061","#5C5B5F","#505960","#595957","#515757","#515153","#4A5353","#494E50","#484C4F","#3971D0","#3A70B6","#3866C3","#3965AF","#396B9A","#386399","#375E96","#2C6EC5","#2C62BA","#1D66C6","#2E6695","#2E5D91","#1F6490","#2F56A7","#2E5794","#2D588A","#2C5388","#1C55A8","#20538C","#375674","#2B5579","#304F70","#255179","#1C5079","#3F495D","#33405A","#2B3F5D","#47484A","#404749","#383F49","#3F4343","#3C3D41","#363D3F","#36373C","#31363A","#1F4886","#15478E","#153E8A","#24486F","#1B4772","#1B3E6D","#273E53","#27394E","#1C4158","#1D3953","#25364B","#1A3650","#293147","#2E3037","#203051","#1F2F41","#2B2E33","#292B31","#242C2F","#242833","#23272C","#21242D","#1F222C","#1E2228","#1B1F27","#1A1D25","#0F2C58","#102737","#101C32","#181B24","#161B22","#141821","#131723","#141721","#131620","#0D1627","#12161F","#121520","#12151F","#10141E","#04142B","#10141C","#080F1E"];
 const packed=["","","","","",""];
 function decode(b64){
  const raw=atob(b64),len=width*height,cel=new Array(len);let p=0;
  if(raw.length%2)throw Error('Bloque RLE incompleto.');
  for(let i=0;i<raw.length;i+=2){
   const n=raw.charCodeAt(i),idx=raw.charCodeAt(i+1);
   if(n<1||idx>=palette.length||p+n>len)throw Error('Fotograma dañado.');
   cel.fill(idx?palette[idx]:null,p,p+n);p+=n;
  }
  if(p!==len)throw Error('Fotograma incompleto.');
  return cel;
 }
 const cels=packed.map(decode);
 return{width,height,fps,frame:0,selected:1,
  layers:[{id:1,name:'Habilidad de hielo · seis poses',visible:true,cels}]};
}